def _build_cyclic(spec) -> ListNode | None:
    values, pos = spec[0], spec[1]
    if not values:
        return None
    dummy = ListNode()
    tail = dummy
    for value in values:
        tail.next = ListNode(value)
        tail = tail.next
    if pos < 0 or pos >= len(values):
        return dummy.next
    node = dummy.next
    for _ in range(pos):
        node = node.next
    tail.next = node
    return dummy.next
